changeSet.sql:
ALTER TABLE im_user DROP CONSTRAINT ck_user_system_google;
ALTER TABLE im_user ADD CONSTRAINT ck_user_system_google CHECK (
    (is_system_user = true AND google_id IS NULL AND pending_google_login = false)
    OR (is_system_user = false AND google_id IS NOT NULL AND pending_google_login = false)
    OR (is_system_user = false AND google_id IS NULL AND pending_google_login = true));
CREATE UNIQUE INDEX uk_user_email_case_insensitive ON im_user (lower(email));
